import React from "react";
import { createUseStyles } from "../../lib/styling";
import { ThemeTokens } from "@airbus/styles";

type Props = {
  width?: string | number;
  height?: string | number;
};

const useStyles = createUseStyles(
  ({ color }: ThemeTokens) => ({
    root: {
      background: color.surface.componentbackground.minimal.light,
      border: `2px solid ${color.border.neutral.moderate.light}`,
    },
    line: {
      strokeWidth: "1px",
      stroke: color.border.neutral.moderate.light,
    },
  }),
  "placeholder"
);

const Placeholder = ({ width = 48, height = 48, ...props }: Props) => {
  const classes = useStyles();
  return (
    <div className={classes.root} style={{ width, height }} {...props}>
      <svg xmlns="http://www.w3.org/2000/svg" style={{ width, height }}>
        <line
          className={classes.line}
          x1={0}
          y1={0}
          x2={`calc(${width} - 4)`}
          y2={`calc(${height} - 4)`}
        />
        <line
          className={classes.line}
          x1={`calc(${width} - 4)`}
          y1={0}
          x2={0}
          y2={`calc(${height} - 4)`}
        />
      </svg>
    </div>
  );
};

export default Placeholder;
